import{at as e,it as t,n,vt as r}from"./chunks/framework.BVWCHfG0.js";var i=JSON.parse(`{"title":"The\xA0scss namespace","description":"","frontmatter":{},"headers":[],"relativePath":"syntaxes/scss.md","filePath":"lib/syntaxes/scss/README.md","lastUpdated":1790710395000}`),a={name:`syntaxes/scss.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="the-scss-namespace" tabindex="-1">The\xA0<code>scss</code> namespace <a class="header-anchor" href="#the-scss-namespace" aria-label="Permalink to “The\xA0scss namespace”">​</a></h1><p>The\xA0rules of\xA0the\xA0core under\xA0<code>@stylistic/scss/&lt;rule&gt;</code>, for\xA0stylesheets written in\xA0<a href="https://sass-lang.com" target="_blank" rel="noreferrer">SCSS</a> and\xA0parsed with\xA0<a href="https://github.com/postcss/postcss-scss" target="_blank" rel="noreferrer"><code>postcss-scss</code></a>. They are configured in\xA0the\xA0<code>overrides</code> block naming that\xA0syntax, as\xA0<a href="/user-guide/custom-syntaxes">Custom syntaxes</a> shows.</p><p>Every rule of\xA0the\xA0core is here, with\xA0the\xA0same options and\xA0the\xA0same documentation, and\xA0plain CSS is read exactly as\xA0the\xA0core reads it\xA0— a\xA0plain block of\xA0an\xA0HTML page beside a\xA0<code>lang=&quot;scss&quot;</code> one included, so\xA0a\xA0mixed page is configured with\xA0these rules alone. What the\xA0namespace reads beyond the\xA0core:</p><ul><li>the\xA0constructs only Sass spells\xA0— placeholder selectors (<code>%a</code>), nested properties (<code>font: { family: x }</code>), <code>@content</code> and\xA0a\xA0reading through\xA0a\xA0module (<code>ns.$a</code>, <code>ns.f()</code>)\xA0— are passed over\xA0the\xA0way the\xA0core passes over\xA0what is not\xA0standard CSS, rather than\xA0misread as\xA0code; a\xA0variable (<code>$a: b</code>) with\xA0its map or\xA0list, and\xA0an\xA0interpolation (<code>#{…}</code>), the\xA0core passes over\xA0as\xA0well, since\xA0a\xA0plugin spells both over\xA0plain CSS;</li><li>an\xA0inline comment (<code>//</code>) is a\xA0comment of\xA0the\xA0file: positions are counted and\xA0fixes written in\xA0the\xA0file as\xA0it is spelled, and\xA0no fix writes into\xA0such a\xA0comment;</li><li><code>function-whitespace-after</code> under\xA0<code>never</code> leaves the\xA0whitespace in\xA0front of\xA0a\xA0<code>+</code> or\xA0a\xA0<code>-</code> standing behind a\xA0call, since\xA0Sass reads such a\xA0sign as\xA0an\xA0operator (see the\xA0rule&#39;s README);</li><li>the\xA0<code>value-slash-space-*</code> and\xA0<code>media-feature-slash-space-*</code> rules pass over\xA0a\xA0solidus Sass divides at\xA0— one beside a\xA0variable or\xA0a\xA0call of\xA0Sass&#39;s own, as\xA0in\xA0<code>4/$a</code> and\xA0<code>fn()/2</code>\xA0— and\xA0read every other solidus as\xA0the\xA0core does, <code>var(--x)/2</code> among them.</li></ul><p>This namespace is about\xA0the\xA0stylistic side of\xA0the\xA0CSS an\xA0SCSS file holds. The\xA0SCSS constructs themselves\xA0— <code>@if</code>/<code>@else</code>, <code>@mixin</code>/<code>@include</code>, variables, placeholders, <code>//</code> comments\xA0— have stylistic rules of\xA0their own in\xA0<a href="https://github.com/stylelint-scss/stylelint-scss" target="_blank" rel="noreferrer">stylelint-scss</a>, which\xA0reads the\xA0same files beside this namespace.</p>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};